import test from "node:test";
import assert from "node:assert/strict";
import { slug } from "../lib/slug.mjs";

test("simple", () => {
  assert.equal(slug("Hello World"), "hello-world");
});

test("empty string", () => {
  assert.equal(slug(""), "");
});

test("unicode input: accented latin is decomposed and stripped", () => {
  assert.equal(slug("Café"), "cafe");
});

test("unicode input: non-latin collapses to empty", () => {
  assert.equal(slug("日本語"), "");
});
